int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac,
                                      struct ceph_authorizer *a,
                                      size_t len)
{
    struct ceph_auth_handler *handler;
    int ret;

    handler = ceph_auth_get_handler(ac, a->service);
    if (!handler)
        return -EINVAL;

    ret = handler->decode_reply(a, len);
    if (ret < 0)
        return ret;

    if (a->decrypted_len != a->expected_decrypted_len) {
        pr_err("decrypted size mismatch: expected %u, got %u",
               a->expected_decrypted_len, a->decrypted_len);
        return -EINVAL;
    }

    if (memcmp(a->nonce, a->expected_nonce, sizeof(a->nonce)) != 0) {
        pr_err("nonce mismatch");
        return -EINVAL;
    }

    pr_debug("authorizer reply verified successfully");
    return 0;
}

int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac, struct ceph_authorizer *a, size_t len)
{
    int ret;
    struct ceph_auth_ticket_handler *handler;

    handler = ceph_auth_client_get_ticket_handler(ac, a->service);
    if (!handler) {
        return -EINVAL;
    }

    ret = handler->decrypt(handler, a->reply, len, a->decrypted, sizeof(a->decrypted));
    if (ret < 0 || (size_t)ret != a->expected_decrypted_size) {
        return -EBADMSG;
    }

    if (memcmp(a->decrypted + 4, a->nonce, CEPH_AUTH_NONCE_LEN)) {
        return -EKEYREJECTED;
    }

    CEPH_DEBUG("Authorizer reply verification succeeded");
    return 0;
}

