int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac,
                                      struct ceph_authorizer *a,
                                      size_t len)
{
    struct ceph_auth_ticket_handler *th;
    int ret;

    th = ceph_auth_get_ticket_handler(ac, a->service);
    if (!th) {
        return -ENOENT;
    }

    ret = ceph_auth_decrypt(ac, a->reply_data, len, th->session_key, &a->decrypted_data);
    if (ret < 0) {
        return ret;
    }

    if (a->decrypted_data.size != a->expected_decrypted_size) {
        return -EBADMSG;
    }

    if (memcmp(a->nonce, a->decrypted_data.nonce, CEPH_AUTH_NONCE_SIZE) != 0) {
        return -EINVAL;
    }

    return 0;
}

int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac, struct ceph_authorizer *a, size_t len)
{
    int ret;
    struct ceph_auth_ticket_handler *th;
    size_t dec_len;
    void *dec_data;

    th = ceph_auth_client_get_ticket_handler(ac, a->service);
    if (!th) {
        return -ENOENT;
    }

    dec_data = th->decrypt(a->reply, len, &dec_len);
    if (!dec_data) {
        return -EIO;
    }

    if (dec_len != a->expected_decrypted_size) {
        free(dec_data);
        return -EINVAL;
    }

    if (memcmp(dec_data + a->nonce_offset, a->expected_nonce, a->nonce_len) != 0) {
        free(dec_data);
        return -EPERM;
    }

    free(dec_data);
    return 0;
}
